# ============================================================== timeout
GUIDES.append(dict(
    name="timeout", section="1", one_line="run a command with a time limit",
    plain=["`timeout` runs a command and stops it if it takes too long. It is the safe way to try something that might hang: a scan, a network connection or a brute-force loop.",
           "When the time is up it sends a signal (TERM by default) to the command. You can add a second, harsher signal (KILL) for commands that ignore the first."],
    when=["Stop a command that may hang (nc, ssh, a script).", "Limit how long a scan or loop runs.", "Use in scripts so one step cannot block everything.", "Give a stubborn process a grace time then kill it."],
    examples=[("Stop after 5 seconds", "timeout 5 ping 127.0.0.1", "Pings for 5 seconds, then timeout ends it."),
              ("Use minutes or hours", "timeout 2m nmap -p- 10.10.10.5", "Suffixes: s seconds (default), m minutes, h hours, d days."),
              ("Check whether it timed out", "timeout 3 sleep 10; echo $?", "The exit status is 124 when the time limit hit. It is the command's own status otherwise."),
              ("Ask first, then kill", "timeout -k 5 20 ./slow_program", "After 20 seconds send TERM; 5 seconds later, if still running, send KILL."),
              ("Send a different signal", "timeout -s INT 10 ./server", "-s chooses the first signal (INT is like pressing Ctrl+C)."),
              ("Run in a script safely", "timeout 10 nc -zv 10.10.10.5 22 || echo 'no answer'", "|| runs the echo if the command fails or times out."),
              ("Keep the command's own exit code", "timeout --preserve-status 5 ./check.sh", "Returns the command's status even if it was cut off by the timer.")],
    options=[
        ("DURATION", "Number with optional suffix s, m, h, d. 0 means no time limit.", "Always."),
        ("-s, --signal=SIGNAL", "Signal to send at the end of the time (default TERM).", "INT, HUP, KILL."),
        ("-k, --kill-after=DURATION", "Also send KILL after this extra time.", "Stubborn processes."),
        ("--preserve-status", "Exit with the command's own status, even on timeout.", "Scripts that read the code."),
        ("--foreground", "Do not create a separate background group; allow keyboard signals to reach the command.", "Interactive commands."),
        ("-v, --verbose", "Print a message when a signal is sent.", "Debugging."),
        ("--help", "Show help.", "A reminder."),
        ("--version", "Show version.", "Check install."),
        ("EXIT STATUS", "124 timed out, 125 timeout itself failed, 126 command cannot be run, 127 command not found, 137 command was killed by KILL.", "Reading $? in scripts.")],
    mistakes=["Putting the duration after the command: it must come first.", "Forgetting that a setuid binary may not be signalled when you wrap it as another user.", "Expecting TERM to stop everything: some programs ignore it, so add -k.", "Using timeout on an interactive shell without --foreground.", "Forgetting 124 means timeout: do not treat it as the command's failure."],
    try_=["Run timeout 3 sleep 10 and print $?.", "Run timeout -k 1 2 sleep 100 and watch it end.", "Use timeout in a loop to test 5 ports with a 2 second limit each."],
    see_also="sleep(1), kill(1), nc(1), ssh(1), watch(1), nohup(1)."))

# ============================================================== paste
GUIDES.append(dict(
    name="paste", section="1", one_line="merge lines of files side by side",
    plain=["`paste` glues files together line by line, like putting columns next to each other. Line 1 of file A and line 1 of file B become one line separated by a tab.",
           "With -s it does the opposite job: it turns one column into one long row. With -d you choose the separator."],
    when=["Combine a username list and a password list into user:pass pairs.", "Turn a column of values into one comma-separated line.", "Number lines or pair them up.", "Build a CSV from separate lists."],
    examples=[("Two files side by side", "paste names.txt scores.txt", "Line 1 of each, joined with a tab, then line 2, and so on."),
              ("Choose the separator", "paste -d: users.txt passwords.txt", "-d sets the delimiter: here user:password pairs, ready for a credentials list."),
              ("One column into a row", "paste -sd, ports.txt", "-s joins all lines of one file into a single line; -d, uses commas. 22, 80, 443 becomes 22,80,443."),
              ("Pair up lines from one file", "paste - - < list.txt", "Each - reads one line from standard input, so two dashes pair up lines two at a time."),
              ("Three columns from commands", "paste <(seq 1 3) <(printf 'a\\nb\\nc\\n') <(seq 10 12)", "Process substitution turns commands into files so you can merge their outputs."),
              ("Several separators in turn", "paste -d',;' a.txt b.txt c.txt", "The separator list is used in rotation: first , then ; ...")],
    options=[
        ("-d, --delimiters=LIST", "Use these characters instead of a tab, taken in turn.", "CSV and colon lists."),
        ("-s, --serial", "Paste one file at a time instead of in parallel (join all lines of each file).", "Column to row."),
        ("-z, --zero-terminated", "Lines end with NUL instead of newline.", "find -print0 output."),
        ("--help", "Show help.", "A reminder."),
        ("--version", "Show version.", "Check install.")],
    mistakes=["Files of different length: paste leaves the missing fields empty.", "Forgetting that the default separator is a TAB, not a space.", "Using -s and expecting columns: it merges lines of each file into one line per file.", "Windows line endings (CRLF) inside the files adding stray carriage returns."],
    try_=["Combine two small lists with paste -d:.", "Turn seq 1 5 into 1,2,3,4,5 with paste -sd,.", "Pair up lines of a file with paste - -."],
    see_also="cut(1), join(1), column(1), sort(1), awk(1), cat(1), tr(1)."))

