# ============================================================== test
GUIDES.append(dict(
    name="test", section="1", one_line="check file types and compare values (also written as [ ... ])",
    plain=["`test` answers yes/no questions: does this file exist, is this string empty, is 5 bigger than 3? It prints nothing; it sets its exit status to 0 for true and 1 for false. Shell scripts use it inside if and while.",
           "The square-bracket form `[ ... ]` is the same command with a closing ] required. In bash, `[[ ... ]]` is a related built-in with extra features (pattern matching and no word-splitting surprises)."],
    when=["Check whether a file or directory exists before using it.", "Compare numbers or strings in a script.", "Test permissions (readable, writable, executable).", "Decide in a script whether you are root."],
    examples=[("Does the file exist?", "test -f notes.txt && echo yes", "-f is true for a regular file. && runs echo only when the test is true."),
              ("Bracket form in an if", "if [ -d /tmp/loot ]; then echo 'folder exists'; fi", "Spaces inside the brackets are required."),
              ("Is the string empty?", "[ -z \"$name\" ] && echo 'name is empty'", "-z true if length zero; -n true if not zero."),
              ("Compare strings", "[ \"$a\" = \"$b\" ] && echo same", "Use = for strings (with spaces around it) and always quote variables."),
              ("Compare numbers", "[ \"$n\" -gt 10 ] && echo big", "-eq -ne -lt -le -gt -ge are for numbers. Using > or < compares nothing useful in [ ]."),
              ("Combine tests", "[ -r file ] && [ -w file ] && echo 'read and write'", "Chain with && or use -a / -o inside (older style)."),
              ("Am I root?", "[ \"$(id -u)\" -eq 0 ] || echo 'run as root'", "id -u prints your numeric user id; root is 0."),
              ("Newer than?", "[ a.txt -nt b.txt ] && echo 'a is newer'", "-nt is newer than, -ot older than, -ef the same file.")],
    options=[
        ("-e FILE", "File exists (any type).", "Existence."),
        ("-f FILE / -d FILE", "Regular file / directory.", "Type checks."),
        ("-L FILE, -h FILE", "Symbolic link.", "Links."),
        ("-r FILE / -w FILE / -x FILE", "Readable / writable / executable by you.", "Permissions."),
        ("-s FILE", "File exists and is not empty.", "Empty file checks."),
        ("-b / -c / -p / -S FILE", "Block device / character device / named pipe / socket.", "Special files."),
        ("-u FILE / -g FILE / -k FILE", "Set-user-ID bit / set-group-ID bit / sticky bit.", "Finding privilege bits."),
        ("-O FILE / -G FILE", "Owned by your user / your group.", "Ownership."),
        ("-N FILE", "Modified since it was last read.", "Change detection."),
        ("F1 -nt F2 / F1 -ot F2 / F1 -ef F2", "Newer than / older than / same file (same inode).", "Comparing files."),
        ("-z STRING / -n STRING", "Empty / not empty.", "Checking variables."),
        ("S1 = S2 / S1 != S2", "Strings equal / not equal.", "Matching text."),
        ("N1 -eq N2, -ne, -lt, -le, -gt, -ge", "Numeric equal, not equal, less, less or equal, greater, greater or equal.", "Number checks."),
        ("! EXPR", "Negate.", "Reversing a test."),
        ("EXPR1 -a EXPR2 / EXPR1 -o EXPR2", "And / or (prefer && and || between tests).", "Combining."),
        ("( EXPR )", "Group tests (escape the parentheses in the shell).", "Complex logic."),
        ("-t FD", "File descriptor is a terminal.", "Interactive or piped check."),
        ("--help / --version", "Help and version.", "Check install.")],
    mistakes=["Missing spaces: [ -f file] or [-f file] fail.", "Not quoting variables: an empty variable removes the argument and breaks the test.", "Using = for numbers or -eq for strings.", "Using > inside [ ] and creating a file named after the number.", "Forgetting that [[ ]] is bash only: scripts for sh must use [ ]."],
    try_=["Write a script that checks a file exists and is readable.", "Test whether a variable is empty or not.", "Compare two numbers with each of the numeric operators."],
    see_also="bash(1), expr(1), find(1), stat(1), ls(1), id(1), and the bash manual section on conditional expressions."))

# ============================================================== getcap
GUIDES.append(dict(
    name="getcap", section="8", one_line="examine file capabilities",
    plain=["Linux can give a program a single piece of root power (a capability) instead of making it fully root. Examples: cap_net_bind_service lets a program use port 80, cap_setuid lets it change its user id, cap_dac_read_search lets it read any file.",
           "`getcap` shows which files carry such capabilities. It matters in privilege-escalation work: a harmless-looking program with a powerful capability (like python with cap_setuid) can be turned into a root shell. `setcap` sets them and `capsh` explains them."],
    when=["Hunt for privilege-escalation routes on a Linux target.", "Audit which binaries have extra privileges (defence).", "Check a service's capabilities.", "Understand what a capability string means."],
    examples=[("Scan the whole system", "getcap -r / 2>/dev/null", "-r goes through every directory below /. 2>/dev/null hides permission errors. Every line is a file with a capability."),
              ("One file", "getcap /usr/bin/ping", "May show cap_net_raw=ep: ping may open raw sockets without being setuid."),
              ("Read the answer", "/usr/bin/python3.8 = cap_setuid+ep", "e means effective, p permitted. cap_setuid+ep on python means any user can call os.setuid(0): an easy path to root."),
              ("Check a running process", "grep Cap /proc/self/status\ncapsh --decode=0000003fffffffff", "The hex values in /proc show a process's capabilities; capsh --decode turns the number into names."),
              ("Set a capability (lab)", "sudo setcap cap_net_bind_service=+ep ./server", "Lets that program bind to ports below 1024 without root."),
              ("Remove it", "sudo setcap -r ./server", "-r removes all capabilities from the file."),
              ("Numeric view", "getcap -n /usr/bin/ping", "-n prints the root id in namespaced capabilities, useful in containers.")],
    options=[
        ("-r", "Search directories recursively.", "Whole-system sweeps."),
        ("-v", "Verbose: also show files with no capabilities.", "Seeing everything."),
        ("-n", "Print the numeric root id of namespaced capabilities.", "Containers."),
        ("-h, --help", "Show help.", "A reminder."),
        ("Common capabilities", "cap_setuid, cap_setgid (change ids), cap_dac_override and cap_dac_read_search (bypass file permissions), cap_net_raw (raw packets), cap_net_bind_service (low ports), cap_sys_admin (broad admin), cap_sys_ptrace (debug others).", "Judging risk."),
        ("Flags e / i / p", "Effective, inheritable, permitted sets.", "Reading =ep, +ep and so on."),
        ("setcap CAPS FILE / setcap -r FILE", "Set or remove capabilities.", "Lab changes."),
        ("capsh --print / --decode=HEX", "Show your capabilities / translate a hex mask.", "Reading /proc values.")],
    mistakes=["Forgetting 2>/dev/null and burying the result in errors.", "Ignoring a hit because it is not setuid: capabilities are a separate privilege route.", "Assuming ping needs capabilities on every system: some use setuid.", "Misreading cap_net_bind_service as dangerous: it is usually harmless; cap_setuid and cap_dac_override are the serious ones.", "Using setcap on files you do not own in a shared lab."],
    try_=["Run getcap -r / 2>/dev/null and list every result.", "Decide which results are dangerous and why.", "Use capsh --decode on the CapEff line of /proc/self/status."],
    see_also="setcap(8), capsh(1), capabilities(7), find(1) (find / -perm -4000), id(1), and GTFOBins for capability abuse."))

# ============================================================== crontab
GUIDES.append(dict(
    name="crontab", section="1", one_line="maintain per-user scheduled jobs (cron tables)",
    plain=["cron runs commands on a schedule: every minute, every night at 02:00, at every reboot. `crontab` is the command that edits your personal schedule.",
           "Each line has five time fields and then a command: minute, hour, day of month, month, day of week. A star * means every.",
           "For security work it matters twice: persistence (an attacker adds a job) and privilege escalation (a root cron job runs a script that you can write to)."],
    when=["Schedule a script to run regularly.", "List what a user has scheduled.", "Hunt a writable root cron script on a target (privilege escalation).", "Find persistence left behind in an incident."],
    examples=[("List your jobs", "crontab -l", "Prints your schedule or 'no crontab for user'."),
              ("Edit your jobs", "crontab -e", "Opens your editor (first time asks which). Save and exit to install."),
              ("A job every 5 minutes", "*/5 * * * * /home/user/check.sh >> /tmp/check.log 2>&1", "*/5 means every 5 minutes. Output goes to a log, otherwise it is mailed or lost."),
              ("A nightly job at 02:30", "30 2 * * * /usr/bin/backup.sh", "Minute 30, hour 2, any day, any month, any weekday."),
              ("Weekdays at 9", "0 9 * * 1-5 /usr/bin/report.sh", "Day of week 1-5 is Monday to Friday."),
              ("At boot", "@reboot /home/user/start.sh", "@reboot, @hourly, @daily, @weekly, @monthly, @yearly are shortcuts."),
              ("Look at another user's jobs (root)", "sudo crontab -l -u alice", "-u names the user."),
              ("Hunt system cron on a target", "cat /etc/crontab; ls -la /etc/cron.d /etc/cron.daily; ls -la /var/spool/cron/crontabs", "System cron files have an extra column for the user to run as. Look for scripts you can write to, and for wildcards in tar or rsync commands."),
              ("Watch what runs without root", "pspy64", "A separate tool that watches processes and reveals cron jobs as they run, even without reading the files.")],
    options=[
        ("-l", "List the current crontab.", "Reading."),
        ("-e", "Edit the crontab.", "Changing."),
        ("-r", "Remove the whole crontab (no confirmation unless -i).", "Cleaning, with care."),
        ("-i", "With -r, ask before deleting.", "Safety."),
        ("-u USER", "Act on this user's crontab (root only).", "Administering."),
        ("-s", "Include the SELinux security context.", "SELinux systems."),
        ("-n HOST", "Set the host that runs the cron jobs (some versions).", "Clusters."),
        ("-V", "Show version.", "Check install."),
        ("FIELDS: m h dom mon dow command", "Minute 0-59, hour 0-23, day of month 1-31, month 1-12, day of week 0-7 (0 and 7 are Sunday).", "Writing a schedule."),
        ("Operators: * , - /", "Every / list / range / step. */10 means every 10.", "Patterns."),
        ("@reboot @hourly @daily @weekly @monthly @yearly", "Shortcuts for common schedules.", "Simple jobs."),
        ("/etc/crontab, /etc/cron.d/, /etc/cron.{hourly,daily,weekly,monthly}/", "System-wide schedules; /etc/crontab and /etc/cron.d need a user field.", "System jobs."),
        ("/etc/cron.allow, /etc/cron.deny", "Control who may use crontab.", "Access control.")],
    mistakes=["Cron has a tiny PATH: use full paths to every program.", "Forgetting 2>&1 and a log, so errors vanish.", "Using % in a command without escaping it as \\%.", "Editing /etc/crontab and leaving out the user column.", "Wiping a crontab with crontab -r when you meant -e.", "Not making scripts executable."],
    try_=["Add a job that appends the date to a file every minute, and watch it.", "List /etc/cron.d on your machine and read each file.", "Find a script run by root cron that is writable by your user (in a lab)."],
    see_also="cron(8), crontab(5), at(1), systemd.timer(5), anacron(8), pspy, and linpeas for privilege-escalation checks."))
